import {money} from './core.mjs';import {dollarImpact,availableAlternatives,rankPortfolio} from './profit-lab-core.mjs';
const $=id=>document.getElementById(id);let data,active='basket';const pct=n=>(100*n).toFixed(1)+'%';const num=n=>Number(n).toFixed(2);const branch=()=>$('lab-branch').value;
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function card(label,value,note,alert=false){const c=el('article',undefined,'lab-card'+(alert?' alert':''));c.append(el('span',label),el('strong',value),el('p',note));return c;}
function table(id,headers,rows){const t=el('table',undefined,'lab-table'),head=el('thead'),r=el('tr');for(const h of headers)r.append(el('th',h));head.append(r);const body=el('tbody');for(const row of rows){const tr=el('tr');for(const v of row)tr.append(el('td',String(v)));body.append(tr);}if(!rows.length){const tr=el('tr'),td=el('td','No items under these assumptions.');td.colSpan=headers.length;tr.append(td);body.append(tr);}t.append(head,body);$(id).replaceChildren(t);}
function options(id,values,previous){$(id).replaceChildren();for(const [value,label]of values){const o=el('option',label);o.value=value;$(id).append(o);}if(values.some(v=>v[0]===previous))$(id).value=previous;}
function basket(){const b=data.modules.basket,old=$('basket-drink').value;options('basket-drink',Object.keys(b.recommendations[branch()]).map(p=>[p,p]),old);$('basket-options').replaceChildren(...b.recommendations[branch()][$('basket-drink').value].map(p=>card(p.product, money(p.unitGP)+' unit GP',`${pct(p.purchaseRate)} smoothed historical co-purchase rate · score ${money(p.score)}. This is not extra profit.`)));const m=b.metrics;table('basket-metrics',['Policy','Hit@1','Hit@3','Matched GP proxy'],Object.entries(m.test).map(([n,v])=>[n,pct(v.hitAt1),pct(v.hitAt3),money(v.matchedUnitGPProxy)]));$('basket-note').textContent=`${m.testBeverageBaskets} June beverage baskets × ${m.foodCandidates} food candidates. ${m.protocol} ${m.interpretation} The conditional profit rule loses to the branch-popularity profit rule on the June matched-GP proxy.`;}
function dollar(){const m=data.modules.dollar,p=m.allMenuCentPolicies.find(r=>r.branch===branch());$('dollar-summary').replaceChildren(card('Whole-cent price step',money(p.priceIncreaseUSD),'Across every menu item at this branch; no change in quantities assumed.'),card('Conditional GP/day',money(p.sameVolumeGPIncreasePerDay),`${num(p.affectedUnitsPerDay)} units and ${num(p.affectedTransactionsPerDay)} transactions affected per day.`),card('Break-even uniform volume loss',pct(p.uniformVolumeLossBreakEven),'A loss above this erases the modeled gain. This is not an elasticity estimate.'));const loss=Number($('volume-loss').value)/100;$('volume-loss-output').textContent=pct(loss);$('dollar-response').textContent=`At ${pct(loss)} assumed uniform volume loss: ${money(dollarImpact(p,loss))} change in gross profit per day.`;table('dollar-skus',['Product','Price increase','Units/day affected','Fixed-volume GP/day'],m.singleSKUUnder5Percent.filter(p=>p.branch===branch()).map(p=>[p.product,money(p.increaseUSD),num(p.affectedUnitsPerDay),money(p.sameVolumeGPIncreasePerDay)]));$('dollar-note').textContent=m.interpretation+' Cashier rounding, price presentation, service cost and customer response need a real test.';}
function substitution(){const m=data.modules.substitution,items=m.items.filter(r=>r.branch===branch()),previous=$('unavailable-product').value;options('unavailable-product',items.map(p=>[p.product,p.product]),previous);const item=items.find(r=>r.product===$('unavailable-product').value),alts=availableAlternatives(item,$('blocked-group').value);$('substitution-options').replaceChildren(...alts.slice(0,3).map(p=>card(p.product,money(p.unitGP)+' unit GP',`Schedule cosine ${num(p.patternCosine)} · assumed groups: ${p.assumedGroups.join(', ')||'unmapped'}. Not an estimated switching rate.`)));if(!alts.length)$('substitution-options').append(card('No candidate','Check recipes and availability','No same-category candidate survives the selected assumed group restriction. We do not invent demand transfer.'));$('substitution-note').textContent=m.interpretation;}
function risk(){const m=data.modules.risk,r=m.nextDay.find(r=>r.branch===branch());$('risk-cards').replaceChildren(card('Lower GP forecast',money(r.lowerGP),`Historical next-day demo: ${r.date}. Not a guaranteed floor.`,r.flag),card('Low-profit reference',money(r.threshold),'Branch Jan–Apr recorded daily GP 20th percentile.'),card('Review flag',r.flag?'Review':'No flag','Flag means the lower forecast crosses the reference; it is not a probability or an automatic intervention.',r.flag));table('risk-metrics',['Method','Quantile loss ↓','Observed lower coverage','Mean lower GP'],Object.entries(m.metrics.June).map(([n,v])=>[n,num(v.pinballLoss),pct(v.lowerBoundCoverage),money(v.meanLowerBound)]));const a=m.metrics.alerts;$('risk-alerts').textContent=`June: ${a.flaggedDays} flagged branch-days; ${a.actualLowDays} actual low-profit days. Alert precision ${pct(a.precision)}, recall ${pct(a.recall)}. Many flags were false alarms; only three events are observed.`;$('risk-note').textContent=m.metrics.protocol+' '+m.metrics.limits;}
function discount(){const m=data.modules.discount,g=m.reviewGroups.filter(p=>p.Branch===branch());$('discount-cards').replaceChildren(card('Network recorded discounts',money(m.totalRecordedDiscountUSD),'Six-month list price less recorded revenue on discounted lines. Exposure, not proven waste.'),card('Discount exposure on <30% margin lines',money(m.lowMarginDiscountUSD),`${m.lowMarginDiscountedLines} discounted lines, all branches.`),card('Negative-GP discounted lines',String(m.negativeGPDiscountedLines),'Positive recorded gross margin still excludes unrecorded operating costs.'));table('discount-table',['Category','Period','Lines','Discount USD','Recorded margin'],g.slice(0,12).map(r=>[r.Category,r.period,r.lines,money(r.discountUSD),pct(r.margin)]));$('discount-note').textContent=m.interpretation+` The unrounded rate formula gives ${money(m.unroundedRateFormulaUSD)}; ${money(m.roundingDifferenceUSD)} is rounding reconciliation, not additional exposure.`;}
function portfolio(){const m=data.modules.portfolio,k=Number($('portfolio-count').value);$('portfolio-count-output').textContent=k;table('portfolio-items',['Product','Forecast units','Historical unit GP','Forecast × margin'],rankPortfolio(m.nextDayItems,branch(),k).map(p=>[p.product,num(p.forecastUnits),money(p.unitGP),money(p.score)]));table('portfolio-metrics',['Top-three policy','June GP captured','Share of actual GP'],Object.entries(m.metrics).map(([n,v])=>[n,money(v.capturedHistoricalGP),pct(v.captureShare)]));$('portfolio-note').textContent=m.interpretation+' The attention-slot slider changes the historical July 1 candidate list only; the June comparison remains fixed at three per branch/day.';}
function crisis(){const m=data.modules.crisis,old=$('crisis-scenario').value;options('crisis-scenario',m.scenarios.map(p=>[p.id,p.title]),old);const s=m.scenarios.find(p=>p.id===$('crisis-scenario').value);table('crisis-metrics',['Policy · all branches','Mean scenario GP','10th percentile GP','Unsold units','Unserved units'],Object.entries(s.policies).map(([n,v])=>[n,money(v.expectedScenarioGP),money(v.scenarioGP10thPercentile),num(v.expectedUnsoldUnits),num(v.expectedUnservedUnits)]));$('crisis-solver').textContent=`Solver status ${s.solver.status}; relative gap ${s.solver.mipGap===null?'unavailable':pct(s.solver.mipGap)}; requested tolerance ${pct(s.solver.relativeGapTolerance)}. ${s.solver.fallbackUsed?'A feasible baseline fallback was used.':''} Scored on 512 fresh simulated draws, separate from the 16 planning draws. The optimized plan is not guaranteed to beat baselines on fresh draws.`;table('crisis-plan',['Product','Stock units','Unit price','Scenario unit cost'],s.recommendations.filter(r=>r.branch===branch()).map(p=>[p.product,p.units,money(p.price),money(p.cost)]));$('crisis-constraints').textContent=JSON.stringify({assumptions:s.assumptions,constraints:s.constraints,recipeServingEquivalents:m.recipeAssumptions},null,2);$('crisis-note').textContent=s.interpretation+' '+m.note;}
const render={basket,dollar,substitution,risk,discount,portfolio,crisis};
for(const button of document.querySelectorAll('[data-panel]'))button.onclick=()=>{active=button.dataset.panel;for(const b of document.querySelectorAll('[data-panel]'))b.setAttribute('aria-pressed',String(b===button));for(const panel of document.querySelectorAll('.lab-panel'))panel.hidden=panel.id!=='panel-'+active;render[active]();};
$('lab-branch').onchange=()=>render[active]();for(const [id,fn]of [['basket-drink',basket],['unavailable-product',substitution],['blocked-group',substitution],['crisis-scenario',crisis]])$(id).onchange=fn;for(const [id,fn]of [['volume-loss',dollar],['portfolio-count',portfolio]])$(id).oninput=fn;
$('lab-export').onclick=()=>{const record={branch:branch(),module:active,asOf:data.asOf,planningDate:data.planningDate,note:'Historical demo evidence and explicit assumptions; no orders or promotions created.',evidence:data.modules[active]};const url=URL.createObjectURL(new Blob([JSON.stringify(record,null,2)],{type:'application/json'})),a=el('a');a.href=url;a.download=`stories-profit-lab-${active}-${branch()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
try{const response=await fetch('./assets/profit-lab.json');if(!response.ok)throw Error('Profit Lab results could not load. Reload to retry.');data=await response.json();$('lab-date').textContent=`HISTORICAL DEMO · records through ${data.asOf}; planning examples for ${data.planningDate}. Historical evidence and assumed scenarios are labelled separately. No live orders, rewards or offers are created.`;$('lab').hidden=false;basket();}catch(e){$('lab-error').textContent=e.message;$('lab-error').hidden=false;}
